// my contribution to
//   https://www.shadertoy.com/view/dlSyWm
// is
// - the symmetry in hitShape
// - generalized teeth counts
// - changed tooth angle to have parallel tooth sides
// - the texturing with ambient lighting
//
// I know that my symmetry code is quite bad here...
// It handles neither texture coordinates, nor normals well.
// It is made to work with SDFs and then extended to raytracing.
// I will try to make a better shader when I have the time.

#define PI 3.14159
#define inf 1e5
#define ROT(a) mat2(cos(a), sin(a), -sin(a), cos(a))
#define M (iMouse.xy/iResolution.xy)
//get camera ray direction
vec3 camera(in vec3 cam_dir, in vec2 uv) {
    vec3 cam_u = vec3(normalize(vec2(cam_dir.y, -cam_dir.x)), 0);
    vec3 cam_v = cross(cam_u, cam_dir) ;
	return normalize(cam_dir*2.0 + uv.x * cam_u + uv.y * cam_v);
}
// raytrace sphere
vec2 sphere( in vec3 ro, in vec3 rd, float ra ) {
    float b = dot(ro,rd);
    float c = dot(ro,ro)-ra*ra;
    float h = b*b - c;
    if(h < 0.) return vec2(inf);
    h = sqrt(h);
    if (c < 0.) return vec2(0,-b+h);
    return vec2(-b-h,-b+h);
}
bool inCone(in vec3 o, in float k) {
    vec3 m=vec3(1,1,k);
    return dot(o,m*o) < 0. && o.z < 0.;
}
// raytrace cone
float cone(in vec3 o, in vec3 d, in float k) {
    vec3 m=vec3(1,1,k);
    o*=m; d*=m;
    float a=2.*dot(d,m*d), b=2.*dot(o,m*d), c=dot(o,m*o);
    if (c < 0. && o.z > 0.) return 0.;
    float D = b*b - 2.*a*c;
    if (D < 0.) return inf;
    float dist = (-b - sqrt(D))/a;
    if (dist < 0. || o.z+d.z*dist < 0.) return inf;
    return dist;
}
float gear(in vec3 o, in vec3 d, in float kk, in float z, in float count, float an) {
    float g = .5*(count/PI);
    float f = kk*1.3/(count+4.);
    float dist = cone(o, d, -kk);
    if (dist >= inf) return inf;
    vec3 p = o+d*dist;
    if (p.z > 0.0) return inf;
    float angle = atan(p.x, p.y)+an;
    float rangle = round(angle*g)/g-an;
    vec2 dir = vec2(cos(rangle), -sin(rangle));
    vec3 oo = o;
    o += d*dist;
    float s = dot(o.xy, dir);
    if (abs(s) > f) {
        s = sign(s);
        float pz = -(-f*s+dot(o.xy, dir))/dot(d.xy, dir);
        if (pz < 0.0) pz = inf;
        rangle += s/g;
        dir = vec2(cos(rangle), -sin(rangle));
        float pzz = -(s*f+dot(o.xy, dir))/dot(d.xy, dir);
        if (pzz < 0.0) pzz = inf;
        float dd = min(pz, pzz);
        vec3 cp = o+d*(dd);
        if (inCone(cp, -kk*kk*kk)) dist += dd;//return inf;
        else dist = inf;
        //dist += dd;
    }
    dist = min(dist, cone(oo, d, -kk*z));
    vec3 pos = oo+d*dist;
    return dist;
}

// sort such that |ro.z| > |ro.x| > |ro.y|
void sym_zxy(inout vec3 ro, inout vec3 rd, inout float t) {
    #define SWAP(o,d) if(abs(o.y)>abs(o.x)){o.xy=o.yx;d.xy=d.yx;t=-t;}
    SWAP(ro.zx,rd.zx)
    SWAP(ro.zy,rd.zy)
    SWAP(ro,rd)
}
// cube mapping for textures
vec3 sym_cube(vec3 p) {
    vec3 a=abs(p);
    if(a.x>a.y&&a.x>a.z)return p.yzx;
    if(a.y>a.z)return p.zxy;
    return p;
}

const mat2 R = ROT(PI/4.);
float hitShape(vec3 ro, vec3 rd, out vec3 local_hit, out float index) {
    float teeth1=round(2.+pow(M.x,2.)*7.)*4., // 4 fold symmetry needed
    teeth2=round(3.+pow(M.y,2.)*12.)*2.; // 2 fold symmetry needed
    if (iMouse.x < 0.) {
        teeth1 = 3.*4.;
        teeth2 = 7.*2.;
    }
    float ratio = teeth1/teeth2,
    g = (PI*2.0)/teeth1*0.5,
    overlap = 2.8 / (teeth1+teeth2+6.),
    m1 = 1.105*teeth1/(teeth1+teeth2)+overlap*.4,
    m2 = 1.105*teeth2/(teeth1+teeth2)+overlap*.4;
    vec3 oo=ro,dd=rd;

    float d0 = 0.0, time = iTime+sin(iTime), s2 = 1.;
    for (int i = 0; i < 4; i++) {
        sym_zxy(ro, rd, time);
        vec2 s=sign(ro.xz);
        time*=s.x*s.y;
        s2*=s.x*s.y;
        rd.xz*=s;
        ro.xz*=s;
        vec3 yo = vec3(ro.y,R*ro.zx), yd = vec3(rd.y,R*rd.zx);

        float d1 = gear(-ro, -rd, m1, .99-overlap/m1, teeth1, g-time),
        d2 = gear(-yo, -yd, m2, .99-overlap/m2, teeth2, time*ratio),
        d = min(d1, d2);
        // compute the 3 possible ways to leave the symmetry cell
        vec3 t3 = vec3(-(ro.x+ro.y)/(rd.x+rd.y), -(ro.x-ro.y)/(rd.x-rd.y), -(ro.x-ro.z)/(rd.x-rd.z));
        float x = min(t3.x>0.?t3.x:inf, min(t3.y>0.?t3.y:inf, t3.z>0.?t3.z:inf))+1e-5;
        if (d < x) {
            index = d1 < d2 ? 0.0 : 1.0;
            float s1 = sign(time);
            vec3 p1 = -(ro+d1*rd), p2 = (-(yo+d2*yd)*vec3(s2,-s1*s2,1));
            vec3 scube = sym_cube(oo+(d1+d0)*dd);
            local_hit = d1 < d2 ? vec3(ROT(abs(time)*sign(scube.z))*scube.xy*vec2(1,sign(scube.z)), scube.z) : vec3(ROT(abs(time)*ratio)*p2.xy, p2.z);
            return d+d0;
        }
        ro = ro+x*rd;
        d0+=x;
    }
    return inf;
}
vec3 tex(vec2 c) {
    float phi = atan(c.y,c.x);
    return clamp(texture(iChannel0, c).rgb * (2. + cos(length(c)*100.-3.*phi))/3. - 0.5*exp(-dot(c,c)/0.002),0.,1.);
}
vec3 getColor(in vec3 ro, in vec3 rd) {
    vec2 bound = sphere(ro, rd, 1.0);
    vec2 innerBound = sphere(ro, rd, 0.8);
    if (bound.x >= inf) return vec3(0);
    vec3 lpos;
    float i, d = hitShape(ro+rd*bound.x, rd, lpos, i)+bound.x;

    float dis = d;
    if (dis >= bound.y) return vec3(0);
    if (dis >= innerBound.x) {
        d = hitShape(ro+rd*innerBound.y, rd, lpos, i)+innerBound.y;
        if (d > bound.y) return vec3(0);
    };
    vec3 p = ro+rd*d;
    float light = exp(.5*(3.-d))*clamp(4.*length(p)-3.,0.,1.)*2.;
    return light*mix(tex(lpos.xy)*mix(vec3(1,.5,.3), vec3(.95,1,.7), i), vec3(.3,.3,.35)*clamp(abs(lpos.x/.015),0.5,1.), smoothstep(0.06,0.04,length(lpos.xy)));
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord.xy-iResolution.xy*0.5)/iResolution.y;
    vec2 m = vec2(iTime*0.5, 0.75*sin(iTime*0.5)+PI*0.5);
    if (iMouse.z > 0.0) m = M*vec2(2.*PI, PI);

    vec3 ro = vec3(sin(m.y) * cos(-m.x), sin(m.y) * sin(-m.x), cos(m.y))*4.25;
    vec3 rd = camera(-normalize(ro), uv);
    vec3 color = getColor(ro, rd);

    fragColor = vec4(color, 1);
}
